#!/usr/bin/env bash
set -euo pipefail
repo_dir="$(cd "$(dirname "$0")/.." && pwd)"
cd "$repo_dir"
# Only source the file generated by init-local.sh or one you trust; shell files execute code.
if [[ -f .env ]]; then set -a; source .env; set +a; fi
: "${DATABASE_PASSWORD:?Set DATABASE_PASSWORD in the environment or .env}"
java_command=java
if [[ -x /workspace/.tools/jdk-21/bin/java ]]; then java_command=/workspace/.tools/jdk-21/bin/java; fi
exec "$java_command" -jar backend/target/aegis-0.1.0.jar
